#!/usr/bin/env bash
# suite-managed (deploy) — regenerated by conform, do not edit by hand.
# Materializes the Life shared packages INSIDE this node's build context.
# Docker cannot follow the npm-link / pip-editable symlinks that `nodes link`
# creates for the host environment: they point outside the context, so the
# packages have to be physically copied in before `docker build` runs.
#
#   frontend -> frontend/vendor/suite-<name>.tgz (@suite/* npm tarballs)
#   backend  -> backend/vendor/<dist>/ (suite-* python source trees)
#
# Both lists are the node's DECLARED packages — its profile plus the `packages`
# of its node.config, exactly what suite.lock.json records and what the two
# Dockerfiles install. Nothing here probes the disk for what "happens to be
# there": a build input that exists only because someone copied it by hand is
# one `git clean -fdx` away from a broken build.
#
# NB (frontend): every package declares `files: ["dist"]` with no prepack script,
# so a bare `npm pack` would produce a tarball holding only the package.json
# (~3 kB) and the frontend would die on its imports. Hence: build FIRST, assert
# dist/ exists, then pack.
#
# Idempotent: safe to re-run before every build, and required after a clean
# clone (both vendor/ dirs are gitignored — generated, never committed).
set -euo pipefail
NODE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$NODE_DIR"
INHERITS="$(grep -oE '"inherits"[[:space:]]*:[[:space:]]*"[^"]+"' node.config | sed -E 's/.*"inherits"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/')"
# Resolved to an ABSOLUTE path, not left as the relative `../Life` the pointer
# holds: `docker run -v` refuses a relative source and reads it as a volume NAME
# instead, so the node-image packing step below would silently mount an empty
# anonymous volume rather than the package sources.
#
# Order (layout-independent, spec 2026-10-15 §2.1): LIFE_FRAMEWORK_DIR, then a
# climb from this node up to the first directory that is the Life framework
# (it holds packages/shared/suite_core and docs/instances.catalog.json), then the
# framework's own resolver (`python -m suite_core.nodes framework-root`, which
# also reads the device registry ~/.life), and only last the legacy `inherits`
# pointer (`../Life`, which presumes a sibling node: from a LINKED node `..` is
# its physical parent, not the framework's).
is_life_root() { [ -d "$1/packages/shared/suite_core" ] && [ -f "$1/docs/instances.catalog.json" ]; }
LIFE_ROOT=""
if [ -n "${LIFE_FRAMEWORK_DIR:-}" ] && is_life_root "$LIFE_FRAMEWORK_DIR"; then
  LIFE_ROOT="$(cd "$LIFE_FRAMEWORK_DIR" && pwd)"
fi
if [ -z "$LIFE_ROOT" ]; then
  CLIMB="$NODE_DIR"
  while [ "$CLIMB" != "/" ] && [ "$CLIMB" != "$(dirname "$CLIMB")" ]; do
    if is_life_root "$CLIMB"; then LIFE_ROOT="$CLIMB"; break; fi
    CLIMB="$(dirname "$CLIMB")"
  done
fi
if [ -z "$LIFE_ROOT" ]; then
  for PYBIN in python3 python; do
    command -v "$PYBIN" >/dev/null 2>&1 || continue
    FOUND="$("$PYBIN" -m suite_core.nodes framework-root 2>/dev/null | tail -n1)" || FOUND=""
    if [ -n "$FOUND" ] && is_life_root "$FOUND"; then LIFE_ROOT="$(cd "$FOUND" && pwd)"; break; fi
  done
fi
if [ -z "$LIFE_ROOT" ] && [ -n "$INHERITS" ] && is_life_root "$(dirname "$INHERITS")"; then
  LIFE_ROOT="$(cd "$(dirname "$INHERITS")" && pwd)"
fi
if [ -z "$LIFE_ROOT" ]; then
  echo "ERROR: Life framework not found: set LIFE_FRAMEWORK_DIR (see docs/instance-resolution.md)" >&2
  exit 1
fi

# Quoted assignment + unquoted expansion: an empty list iterates zero times
# instead of being a syntax error (a backend-only node has no @suite/*, a
# frontend-only node has no suite-*).
SUITE_PACKAGES=""
SUITE_PY_PACKAGES="suite-backend-core"

# ------------------------------------------------------ backend: python sources
# Deliberately FIRST, before the npm section. The two halves are independent,
# but `set -e` makes the script die on the first failure — and the frontend half
# needs node/npm, which the deploy host does NOT have (the minipc builds images
# with Docker only). Running npm first meant `node: command not found` aborted
# the script before the backend was ever vendored: the backend half was
# unreachable exactly where it matters. Ordering is the fix rather than
# swallowing the npm error, because a frontend node whose tarballs are missing
# must still fail loudly — it just must not take the backend down with it.
#
# Copied as a source tree (not an sdist) so no build backend is needed here: the
# backend image runs `pip install /app/backend/vendor/<dist>`, which resolves the
# package's own transitive dependencies from its pyproject.toml.
# The destination is wiped first so a package renamed or a module deleted
# upstream cannot survive as a stale leftover inside the image.
PY_VENDOR_DIR="$NODE_DIR/backend/vendor"
for DIST in $SUITE_PY_PACKAGES; do
  # suite-backend-core -> <life>/packages/backend-core (same mapping as linker.py)
  PKG_DIR="$LIFE_ROOT/packages/${DIST#suite-}"
  [ -f "$PKG_DIR/pyproject.toml" ] || { echo "ERROR: python package '$DIST' not found in $PKG_DIR" >&2; exit 1; }

  DEST="$PY_VENDOR_DIR/$DIST"
  rm -rf "$DEST"
  mkdir -p "$DEST"
  # tar-pipe rather than cp -r: it applies the excludes in one pass, so the
  # build context never receives a host .venv (hundreds of MB) or stale bytecode.
  ( cd "$PKG_DIR" && tar -cf - \
      --exclude=./.venv --exclude=./.git --exclude=./tests \
      --exclude=./dist --exclude=./build \
      --exclude='*.egg-info' --exclude='__pycache__' --exclude='.pytest_cache' \
      . ) | tar -xf - -C "$DEST"
  [ -f "$DEST/pyproject.toml" ] || { echo "ERROR: vendoring of '$DIST' produced no pyproject.toml" >&2; exit 1; }
  echo "✓ backend/vendor/$DIST ready"
done

# ------------------------------------------------------- frontend: npm tarballs
# Packing needs a node toolchain, and the host that BUILDS the images is not
# necessarily the host that develops on them: the deploy host (the minipc) has
# Docker and no node at all, so this half used to abort with `npm: command not
# found` and every frontend there was simply unbuildable. Installing node on
# each build host is the worse answer — the one toolchain such a host is
# guaranteed to have is the one it builds images with. So: use the host's npm
# when it exists, otherwise run the very same commands inside a throwaway node
# image. Same steps, same result, no per-host prerequisite.
#
# Run as the invoking uid: a root-owned node_modules/ left inside Life's
# packages/ would break the developer's own npm on the next host-side build.
VENDOR_DIR="$NODE_DIR/frontend/vendor"
NODE_IMAGE="${SUITE_NODE_IMAGE:-node:20-alpine}"

# Docker Desktop on Windows receives native paths, while the script runs under
# Git Bash (POSIX paths like /d/srv/Life). Convert the HOST side of each bind
# mount and stop MSYS from rewriting the CONTAINER side (/src, /vendor) into a
# Windows path: `docker run -v /d/srv/Life/packages:/src` otherwise becomes
# a path inside the Git for Windows install dir, which fails on a clean Windows clone.
to_host_path() {
  if command -v cygpath >/dev/null 2>&1; then
    cygpath -w "$1"
  else
    printf '%s' "$1"
  fi
}
LIFE_PACKAGES_HOST="$(to_host_path "$LIFE_ROOT/packages")"
VENDOR_HOST="$(to_host_path "$VENDOR_DIR")"

# ONE script, run either way — the locations it works on are parameters, so the
# host path and the container path cannot drift into doing different things.
# Build only when the package declares a build script (dist/ is what `files`
# ships); npm install is required because the devDeps (tsup/vite) do the build.
PACK_STEPS='set -e
if [ -n "${COPY_FROM:-}" ]; then
  rm -rf "$PKG_ROOT"
  mkdir -p "$PKG_ROOT"
  cp -a "$COPY_FROM"/. "$PKG_ROOT"/
  rm -rf "$PKG_ROOT/$PKG/node_modules"
  cd "$PKG_ROOT/$PKG"
else
  cd "$PKG_MOUNT"
fi
if node -e "var p=require(\"./package.json\");process.exit(p.scripts&&p.scripts.build?0:1)"; then
  npm install --no-audit --no-fund --silent
  node -e "var p=require(\"./package.json\");var d=Object.assign({},p.dependencies||{},p.devDependencies||{});var fs=require(\"fs\");var path=require(\"path\");Object.keys(d).forEach(function(k){var v=d[k];if(typeof v===\"string\"&&v.indexOf(\"file:\")===0){var t=path.resolve(process.cwd(),v.slice(5));if(!fs.existsSync(path.join(t,\"package.json\"))){console.error(\"file: dependency \"+k+\" (\"+v+\") target missing: \"+t);process.exit(1)}}})"
  npm run build --silent
  [ -d dist ] || { echo "ERROR: build of $PKG produced no dist/" >&2; exit 1; }
fi
TGZ="$(npm pack --pack-destination "$VENDOR_MOUNT" | tail -n1)"
mv -f "$VENDOR_MOUNT/$TGZ" "$VENDOR_MOUNT/suite-$PKG.tgz"'

# Host npm builds on a throwaway COPY too, never in place: Life's root declares
# npm `workspaces` (packages/design-system, i18n, ...), so an `npm install` run
# inside packages/<pkg> acts on the whole workspace — it rewrites Life's root
# package-lock.json and leaves the package's own devDeps (tsup) uninstalled,
# which is exactly how the build died on a clean Windows clone (Network#52).
# Outside Life the copy is a plain standalone package. ONE copy for the whole
# loop: a package built first (design-system) leaves its dist/ where the next
# one's `file:../design-system` finds it. node_modules/ and .venv/ are left
# behind — they are host artefacts, rebuilt by the install, and huge.
HOST_WORK=""
if [ -n "$SUITE_PACKAGES" ] && command -v npm >/dev/null 2>&1; then
  HOST_WORK="$(mktemp -d)"
  trap 'rm -rf "$HOST_WORK"' EXIT
  mkdir -p "$HOST_WORK/packages"
  ( cd "$LIFE_ROOT/packages" && tar -cf -       --exclude='node_modules' --exclude='.venv' --exclude='.git'       --exclude='__pycache__' --exclude='.pytest_cache'       . ) | tar -xf - -C "$HOST_WORK/packages"
fi

for PKG in $SUITE_PACKAGES; do
  mkdir -p "$VENDOR_DIR"
  PKG_DIR="$LIFE_ROOT/packages/$PKG"
  [ -f "$PKG_DIR/package.json" ] || { echo "ERROR: package '$PKG' not found in $PKG_DIR" >&2; exit 1; }

  if command -v npm >/dev/null 2>&1; then
    PKG="$PKG" PKG_MOUNT="$HOST_WORK/packages/$PKG" VENDOR_MOUNT="$VENDOR_DIR" sh -c "$PACK_STEPS"
  else
    # The whole `packages/` dir is mounted READ-ONLY and copied in, not just the
    # one package being packed (issue #97): `@suite/domain-ui` depends on
    # `"@suite/design-system": "file:../design-system"`, and a sibling relative
    # path only resolves if the sibling was copied alongside. Mounting `$PKG_DIR`
    # alone left `/tmp/design-system` nonexistent, `npm install` then left a
    # dangling symlink and `tsup` died on the missing types. Building on a COPY
    # (not the shared tree) also keeps `npm install` from writing node_modules/
    # into Life's packages/ (which is both a mutation and, run as a non-writable
    # uid, an EACCES — measured on the minipc).
    MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*' docker run --rm -u "$(id -u):$(id -g)" \
      -v "${LIFE_PACKAGES_HOST}:/src:ro" -v "${VENDOR_HOST}:/vendor" \
      -e PKG="$PKG" -e COPY_FROM=/src -e PKG_ROOT=/tmp/packages -e VENDOR_MOUNT=/vendor \
      -e npm_config_cache=/tmp/.npm -e HOME=/tmp \
      "$NODE_IMAGE" sh -c "$PACK_STEPS"
  fi
  echo "✓ frontend/vendor/suite-$PKG.tgz ready"
done

# Dashboard widgets are generated by node frontends before Vite builds. Their
# usual scripts point at a sibling Life checkout, which Docker cannot see, and
# their output is deliberately gitignored. Generate them here, after package
# vendoring has built the design-system dist the generator imports.
FRONTEND_PATH="$NODE_DIR/frontend"
WIDGET_DIST="$LIFE_ROOT/packages/design-system/dist/index.js"
if grep -Eq '"pre(dev|build)"[[:space:]]*:[[:space:]]*"[^"]*generate-dashboard-widgets\.mjs' "$FRONTEND_PATH/package.json"; then
  if ! command -v node >/dev/null 2>&1; then
    echo "ERROR: dashboard widget generation requires host node (package.json predev/prebuild uses generate-dashboard-widgets.mjs)" >&2
    exit 1
  fi

  # HOST_WORK is the standalone copy built while packing. Materialize its
  # design-system dist where the generator's ../dist/index.js import expects it.
  # Only when missing: never replace a dist other builds may be reading.
  if [ ! -f "$WIDGET_DIST" ] && [ -n "$HOST_WORK" ] && [ -f "$HOST_WORK/packages/design-system/dist/index.js" ]; then
    cp -a "$HOST_WORK/packages/design-system/dist" "$LIFE_ROOT/packages/design-system/dist"
  fi
  [ -f "$WIDGET_DIST" ] || { echo "ERROR: dashboard widget generator requires $WIDGET_DIST; vendoring did not build it" >&2; exit 1; }

  # Read only the lifecycle scripts, rewrite the checkout-relative generator
  # path, and de-duplicate scripts that write the same generated file.
  WIDGET_COMMANDS="$(cd "$FRONTEND_PATH" && LIFE_ROOT="$LIFE_ROOT" node -e 'var p=require("./package.json"),s=p.scripts||{},seen={};["predev","prebuild"].forEach(function(n){var c=s[n];if(typeof c!=="string"||c.indexOf("generate-dashboard-widgets.mjs")<0)return;var m=c.match(/--out(?:=|[ \t]+)(?:"([^"]+)"|\x27([^\x27]+)\x27|([^ \t]+))/),k=m?(m[1]||m[2]||m[3]):c;if(seen[k])return;seen[k]=1;console.log(c.replace(/(?:\.\.\/)+Life\/packages\/design-system\/scripts\/generate-dashboard-widgets\.mjs/g,"$LIFE_ROOT/packages/design-system/scripts/generate-dashboard-widgets.mjs"));})')"
  if [ -n "$WIDGET_COMMANDS" ]; then
    while IFS= read -r WIDGET_COMMAND; do
      [ -n "$WIDGET_COMMAND" ] || continue
      ( cd "$FRONTEND_PATH" && eval "$WIDGET_COMMAND" )
    done <<EOF
$WIDGET_COMMANDS
EOF
  fi
fi

# Theme layer of this node (Life#146): frontend/src/suite-theme.css is rebuilt
# from node.config "theme" right before the image, so the image always carries
# the theme the node declares even if nobody re-ran conform after an edit. Only
# where conform already introduced the file, and only with a host node (the
# engine is the package's own dist, built just above).
SUITE_THEME="$NODE_DIR/frontend/src/suite-theme.css"
if [ -f "$SUITE_THEME" ] && [ -f "$LIFE_ROOT/packages/design-system/dist/theme-engine.js" ] \
  && command -v node >/dev/null 2>&1; then
  # The same command conform uses (instance resolved from the device layout).
  THEME_OK=""
  for PYBIN in python3 python; do
    command -v "$PYBIN" >/dev/null 2>&1 || continue
    if PYTHONPATH="$LIFE_ROOT/packages/shared" "$PYBIN" -m suite_core.nodes theme render "$NODE_DIR" \
      > "$SUITE_THEME.new" 2>/dev/null; then
      THEME_OK=1
      break
    fi
  done
  if [ -n "$THEME_OK" ] && [ -s "$SUITE_THEME.new" ]; then
    mv -f "$SUITE_THEME.new" "$SUITE_THEME"
    echo "✓ frontend/src/suite-theme.css rigenerato"
  else
    rm -f "$SUITE_THEME.new"
    echo "WARN: suite-theme.css non rigenerato (resta quello di conform)" >&2
  fi
fi
